 internal sealed record Frame(string Path,JsonObject Parent,JsonObject Graph,FunctionSignature Signature);
 internal sealed record Chain(Frame[] Frames,string CallKey);
 static JsonObject Entry(Frame frame)=>frame.Graph["nodes"]!.AsArray().OfType<JsonObject>().Single(n=>Forward(n));
