 internal static HashSet<string> Prepare(string id,string text,JsonObject original,JsonObject root,FunctionSignature signature,Element before,Element after,JsonObject remap,JsonObject plans,HashSet<string> used,JsonObject bodies,HashSet<string> selectedBodies)
